class.description:
The server hands a game one of [NetwJoinRequest], [NetwActionRequest], [NetwControlRequest] or [NetwLifecycleRequest]. Each one has the [member peer_id] of the peer that asked, and [method deny] records the [member code] and [member reason] the peer that asked receives.
[codeblock]
func judge(request: NetwRequest) -> void:
    if banned.has(request.peer_id):
        request.deny("You are banned.", ERR_UNAUTHORIZED)
[/codeblock]
